);

function ar_translate( $value ) {
    global $translations;
    if ( is_array( $value ) ) return array_map( 'ar_translate', $value );
    if ( ! is_string( $value ) ) return $value;
    return $translations[ $value ] ?? strtr( $value, $translations );
}

$pages = get_posts( array( 'post_type' => 'page', 'post_status' => 'publish', 'numberposts' => -1 ) );
$seed_path = dirname( __DIR__ ) . '/tools/arabic-content.seed.json';
$seed = is_readable( $seed_path ) ? json_decode( (string) file_get_contents( $seed_path ), true ) : array();
$seed = is_array( $seed ) ? $seed : array();
$seed['pages'] = array_values( array_filter( (array) ( $seed['pages'] ?? array() ), static function ( $item ) {
    return is_array( $item ) && isset( $item['slug'] ) && ( 'home' === $item['slug'] || str_ends_with( (string) $item['slug'], '_ar' ) );
} ) );
$seed['treatments'] = (array) ( $seed['treatments'] ?? array() );
$seed['doctors'] = (array) ( $seed['doctors'] ?? array() );
foreach ( $pages as $page ) {
    if ( str_ends_with( $page->post_name, '_ar' ) || 'home' === $page->post_name ) continue;
    $raw = get_post_meta( $page->ID, BROUNHALL_PAGE_DATA_META, true );
    $data = json_decode( (string) $raw, true );
    if ( ! is_array( $data ) ) continue;
    $seed['pages'][] = array( 'slug' => $page->post_name, 'status' => 'publish', 'title' => ar_translate( $page->post_title ), 'data' => ar_translate( $data ) );
}
$output = json_encode( $seed, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_PRETTY_PRINT ) . PHP_EOL;
file_put_contents( $seed_path, $output );
echo 'Generated ' . count( $seed['pages'] ) . ' Arabic pages and preserved ' . count( $seed['treatments'] ) . " treatments.\n";
